class Exporter {
    private final Path tempFile;

    // inner (the default in Java): holds Exporter.this
    class Cleanup implements Runnable {
        public void run() { deleteQuietly(tempFile); }
    }

    // static nested: holds only what you pass in
    static class SafeCleanup implements Runnable {
        private final Path file;
        SafeCleanup(Path file) { this.file = file; }
        public void run() { deleteQuietly(file); }
    }
}

