final class TempExport implements AutoCloseable {
    private static final Cleaner CLEANER = Cleaner.create();
    private final Path file;
    private final Cleaner.Cleanable cleanable;

    TempExport() throws IOException {
        file = Files.createTempFile("export-", ".csv");
        cleanable = CLEANER.register(this, new Delete(file));   // Delete holds the path, not this
    }

    private record Delete(Path file) implements Runnable {
        public void run() {
            try { Files.deleteIfExists(file); } catch (IOException ignored) { }
        }
    }

    Path file() { return file; }

    @Override public void close() { cleanable.clean(); }        // at most once
}

